# настройки размеров прямо в конвертере: ограничение, пределы, группы, составные, повторное открытие, сайт
import pathlib,re,json
exec(open(pathlib.Path(__file__).with_name('browser.py')).read().split('with sync_playwright() as p:')[0])
with sync_playwright() as p:
    b=p.chromium.launch();ctx=b.new_context(accept_downloads=True,viewport={'width':1500,'height':900});ctx.route('**/*',route);errors=[]
    def page(path):
        g=ctx.new_page();g.on('pageerror',lambda e:errors.append(f'{path.name}: {e}'));g.on('dialog',lambda d:d.accept());g.goto(path.as_uri());g.wait_for_timeout(1200);return g
    def save(g,click,name):
        with g.expect_download(timeout=15000) as d: click()
        f=T/name;d.value.save_as(f);return f
    c=page(OUT/'Конвертер-OBJ-HTML.html');c.set_input_files('#f',str(T/'project-set.html'));c.wait_for_timeout(2000)
    V=lambda g=c:g.evaluate('()=>{const v=geoVals(g,st),o={};for(const k in v)o[k]=+v[k].toFixed(2);return o}')
    K=lambda g=c:g.evaluate('()=>plist().map(p=>p.key)')
    def mv(key,val,g=c):
        g.evaluate('([k,v])=>{const r=ROWS[k].rg;r.value=v;r.dispatchEvent(new Event("input",{bubbles:true}))}',[key,val]);g.wait_for_timeout(250)
    def rw(key,g=c):return g.locator('#axes .row').nth(g.evaluate('k=>[...document.querySelectorAll("#axes .row")].indexOf(ROWS[k].rg.closest(".row"))',key))
    def sel(loc,v):loc.select_option(v);loc.page.wait_for_timeout(300)
    def num(loc,v):loc.fill(str(v));loc.press('Enter');loc.evaluate('e=>e.isConnected&&e.blur()') if False else None;loc.page.wait_for_timeout(300)
    def gear(key,g=c):rw(key,g).locator('.gear').click();g.wait_for_timeout(300)
    print('Настройки размера')
    ok('четыре размера, у каждого кнопка ⚙',K()==['sc','q0','q1','q2','q3'] and c.locator('#axes .gear').count()==4,(K(),c.locator('#axes .gear').count()))
    gear('q1');t=rw('q1').locator('.dset').inner_text()
    ok('в настройках: ограничение, синхронизация, пропорции','Ограничить существующим размером' in t and 'Синхр.' in t and 'Пропорц.' in t,t)
    # ограничение другим размером
    rw('q1').locator('.ron').check();c.wait_for_timeout(300);r=rw('q1');sel(r.locator('.rsel'),'0');num(rw('q1').locator('.rval'),0.25)
    ok('паз ≤ ширина×0.25: сразу уменьшился до 30',V()['q1']==30 and '≤ 30' in rw('q1').locator('.rcap').inner_text(),(V()['q1'],rw('q1').inner_text()))
    mv('q1',100);ok('ползунок не выходит за предел',abs(V()['q1']-30)<=.06,V())
    mv('q0',160);mv('q1',100);ok('ширина 160 — паз можно до 40',abs(V()['q1']-40)<=.06 and abs(V()['q0']-160)<=.01,V())
    rw('q1').locator('.ron').uncheck();c.wait_for_timeout(300);mv('q1',50);ok('снятое ограничение не действует',V()['q1']==50,V())
    c.click('#rs');c.wait_for_timeout(400)
    # лимит в мм и %
    r=rw('q1');num(r.locator('.mx'),60);mv('q1',500);ok('лимит «до» 60 мм',abs(V()['q1']-60)<=.06 and V()['q0']==120,V())
    sel(rw('q1').locator('.lu'),'pct');r=rw('q1');ok('после «от/до» стоит %, выбор неподвижной точки не сжат','%' in r.locator('.dqx').first.inner_text() and r.locator('select.an').bounding_box()['width']>60,r.locator('select.an').bounding_box())
    ok('тот же предел в процентах',abs(float(r.locator('.mx').input_value())-142.86)<.01,r.locator('.mx').input_value())
    num(r.locator('.mx'),200);mv('q1',500);ok('«до» 200% = 84 мм',abs(V()['q1']-84)<=.06,V())
    c.click('#rs');c.wait_for_timeout(400)
    # синхронизация
    sel(rw('q1').locator('.grp-g'),'new');gear('q3');sel(rw('q3').locator('.grp-g'),'1')
    ok('второй паз стал ведомым: виден, галочка «на сайт» снята',not rw('q3').locator('.chk').is_checked() and rw('q1').locator('.chk').is_checked())
    ok('«Все ползунки» остаётся отмеченным',c.locator('#allOn').is_checked())
    gear('q1');num(rw('q1').locator('.gnm'),'Пазы') if False else None
    n=rw('q1').locator('.gnm') if rw('q1').locator('.gnm').count() else None
    if n is None:gear('q1');n=rw('q1').locator('.gnm')
    n.fill('Пазы');n.evaluate('e=>e.dispatchEvent(new Event("change"))');c.wait_for_timeout(300)
    ok('имя группы и состав видны','Пазы' in rw('q3').inner_text() and 'Паз 2' in rw('q1').inner_text(),rw('q1').inner_text())
    mv('q1',45);v=V();ok('синхронные пазы получают одно значение',v['q1']==45 and v['q3']==45,v)
    sel(rw('q3').locator('.grp-g'),'0');ok('вышел из группы — галочка вернулась',rw('q3').locator('.chk').is_checked())
    mv('q1',50);ok('и больше не следует',V()['q3']==45,V())
    sel(rw('q1').locator('.grp-g'),'0');c.click('#rs');c.wait_for_timeout(400)
    # пропорции
    if not rw('q2').locator('.dset').count():gear('q2')
    sel(rw('q1').locator('.grp-pg'),'new');sel(rw('q2').locator('.grp-pg'),'1');mv('q1',63);v=V();ok('пропорция: паз ×1.5 — стенка ×1.5',v['q1']==63 and v['q2']==18,v)
    sel(rw('q2').locator('.grp-pg'),'0');sel(rw('q1').locator('.grp-pg'),'0');c.click('#rs');c.wait_for_timeout(400)
    for k in ['q1','q2','q3']:
        if rw(k).locator('.dset').count():gear(k)
    print('Составные размеры')
    c.click('#cmAdd');c.wait_for_timeout(400);r=rw('c0')
    ok('пустая карточка: ползунок неактивен, три... четыре размера на выбор',r.locator('input[type=range]').is_disabled() and r.locator('input[data-m]').count()==4 and 'минимум два' in r.inner_text(),r.inner_text())
    r.locator('input[data-m="1"]').check();c.wait_for_timeout(300);ok('с одним размером ещё неактивна',rw('c0').locator('input[type=range]').is_disabled())
    rw('c0').locator('input[data-m="2"]').check();c.wait_for_timeout(300);r=rw('c0')
    ok('с двумя — работает, сумма 54, пределы 27…108',not r.locator('input[type=range]').is_disabled() and '54 мм = 42 + 12' in r.inner_text() and r.locator('.mn').input_value()=='27' and r.locator('.mx').input_value()=='108',r.inner_text())
    mv('c0',81);v=V();ok('составной меняет паз и стенку',v['q1']==63 and v['q2']==18,v)
    ok('сумма в настройках обновляется','81 мм = 63 + 18' in rw('c0').inner_text(),rw('c0').inner_text())
    ok('у входящих пометка',c.locator('#axes .cmin').count()==2)
    rw('c0').locator('input[data-m="0"]').check();c.wait_for_timeout(300);ok('предупреждение о перекрытии','Перекрывающиеся' in rw('c0').inner_text(),rw('c0').inner_text())
    rw('c0').locator('input[data-m="0"]').uncheck();c.wait_for_timeout(300);c.click('#rs');c.wait_for_timeout(400)
    # удаление и перенумерация
    c.click('#cmAdd');c.wait_for_timeout(400)
    for m in ['2','3']:rw('c1').locator(f'input[data-m="{m}"]').check();c.wait_for_timeout(250)
    rw('c1').locator('input.lt').fill('Второй');rw('c1').locator('.chk').uncheck();c.wait_for_timeout(300)
    rw('c0').locator('.cmdel').click();c.wait_for_timeout(400)
    ok('после удаления первого второй сохранил имя и снятую галочку',K()[-1]=='c0' and rw('c0').locator('input.lt').input_value()=='Второй' and not rw('c0').locator('.chk').is_checked() and c.locator('#axes .cmin').count()==2,(K(),rw('c0').inner_text()))
    rw('c0').locator('.chk').check();c.wait_for_timeout(200)
    c.click('#cmAdd');c.wait_for_timeout(400);ok('третий, пустой, добавлен',K()[-1]=='c1')
    rw('q0').locator('.dqk input').check();c.wait_for_timeout(300);ok('у пустого составного нет предупреждения о замке',rw('c1').locator('.dqn:visible',has_text='замок').count()==0,rw('c1').inner_text());rw('q0').locator('.dqk input').uncheck();c.wait_for_timeout(300);c.click('#rs');c.wait_for_timeout(300)
    # масштаб
    c.locator('#scOn').uncheck();c.wait_for_timeout(300);ok('масштаб можно убрать',K()[0]=='q0',K())
    c.locator('#scOn').check();c.wait_for_timeout(300);ok('и вернуть',K()[0]=='sc' and rw('sc').locator('.chk').is_checked(),K())
    # прокрутка и шрифт
    c.evaluate('()=>$("panel").scrollTop=200');y=c.evaluate('()=>$("panel").scrollTop')
    c.evaluate('()=>ROWS.q3.rg.closest(".row").querySelector(".gear").click()');c.wait_for_timeout(300)
    ok('открытие настроек не сбрасывает прокрутку',y>0 and abs(c.evaluate('()=>$("panel").scrollTop')-y)<2,(y,c.evaluate('()=>$("panel").scrollTop')))
    c.click('#fzp');c.click('#fzp');ok('ваше оформление: A+ увеличивает шрифт',c.evaluate('()=>$("panel").style.getPropertyValue("--fz")')=='1.2')
    c.click('#fzm');c.click('#fzm');c.click('#dataHead');ok('карточка «Данные для сайта» сворачивается',c.evaluate('()=>$("convBox").classList.contains("collapsed")'));c.click('#dataHead')
    # настройки для сохранения: паз ≤ ширина×0.5, синхронные пазы, составной «Второй», замок на ширине
    sel(rw('q1').locator('.grp-g') if rw('q1').locator('.grp-g').count() else (gear('q1') or rw('q1').locator('.grp-g')),'new')
    if not rw('q3').locator('.dset').count():gear('q3')
    sel(rw('q3').locator('.grp-g'),'1')
    rw('q1').locator('.ron').check();c.wait_for_timeout(300);sel(rw('q1').locator('.rsel'),'0');num(rw('q1').locator('.rval'),0.5)
    rw('q0').locator('.dqk input').check();c.wait_for_timeout(300)
    c.mouse.move(5,500);c.screenshot(path=str(T/'conv-set.png'))
    c.evaluate('()=>$("panel").scrollTop=9999');c.screenshot(path=str(T/'conv-set2.png'))
    c.click('#rs');c.wait_for_timeout(300)
    c.click('#bd');c.wait_for_timeout(2500)
    names=c.evaluate('()=>[...document.querySelectorAll("tbody input")].map(i=>i.value)')
    ok('в окне перевода есть «Второй» и нет пустого составного','Второй' in names and not any('Составной' in n for n in names),names)
    c.click('#trOk');c.wait_for_timeout(500);model=save(c,lambda:c.click('#bd'),'model-set.html')
    e=json.loads(re.search(r'<script id="embed" type="application/json">(.*?)</script>',model.read_text(),re.S).group(1))
    s=e['geo']['st'];ok('в модели: группа, ограничение, замок, один составной',s['dm'][1].get('g')==1 and s['dm'][3].get('g')==1 and s['dm'][1].get('rf')==0 and s['lk']=={'0':1} and len(s['cm'])==1 and s['cm'][0]['m']==[2,3] and 'q3' in e['ui']['off'],(s.get('cm'),s.get('lk'),e['ui']['off']))
    ok('название составного сохранено',e['ui']['lab'].get('c0',{}).get('ru')=='Второй',e['ui']['lab'])
    print('Готовый файл модели')
    vw=page(model);ok('открывается: нет настроек, скрытый ведомый не показан',vw.locator('#axes .gear').count()==0 and vw.locator('#cmAdd').count()==0 and vw.locator('#axes .row').count()==5,vw.locator('#axes .row').count())
    mv('c0',70,vw);v=V(vw);ok('составной в нём работает',v['c0']>54,v)
    print('Повторное открытие в конвертере')
    r=page(OUT/'Конвертер-OBJ-HTML.html');r.set_input_files('#f',str(model));r.wait_for_timeout(2000)
    ok('готовая модель открывается для настройки',K(r)==['sc','q0','q1','q2','q3','c0'] and r.locator('#axes .gear').count()==5 and r.locator('#cmAdd').count()==1,(K(r),r.locator('#info').inner_text()))
    ok('галочки и название на месте',not rw('q3',r).locator('.chk').is_checked() and rw('c0',r).locator('input.lt').input_value()=='Второй' and rw('q0',r).locator('.dqk input').is_checked())
    gear('q1',r);ok('ограничение и группа на месте',rw('q1',r).locator('.ron').is_checked() and rw('q1',r).locator('.rval').input_value()=='0.5' and rw('q1',r).locator('.grp-g').input_value()=='1')
    ok('имя и «Единицы» заблокированы',r.locator('#unit').is_disabled() and r.locator('#thr').is_disabled() and r.locator('#nr').input_value()=='project-set',r.locator('#nr').input_value())
    rw('q1',r).locator('.ron').uncheck();r.wait_for_timeout(300);r.click('#bd');r.wait_for_timeout(2500);r.click('#trOk');r.wait_for_timeout(500)
    m2=save(r,lambda:r.click('#bd'),'model-set2.html');s2=json.loads(re.search(r'<script id="embed" type="application/json">(.*?)</script>',m2.read_text(),re.S).group(1))
    ok('изменение сохраняется повторно',s2['geo']['st']['dm'][1].get('rf') is None and s2['id']==e['id'] and len(s2['geo']['st']['cm'])==1)
    r.set_input_files('#f',str(T/'project-set.html'));r.wait_for_timeout(2000);ok('после этого обычный проект открывается, «Единицы» снова доступны',not r.locator('#unit').is_disabled() and K(r)==['sc','q0','q1','q2','q3'])
    print('Сайт')
    s=page(OUT/'Редактор-сайта.html');s.set_input_files('#fSite',str(T/'site-cfg.html'));s.wait_for_timeout(800)
    ids=s.evaluate('()=>[...document.querySelectorAll("input[type=file]")].map(e=>[e.id,e.multiple])')
    s.set_input_files('#'+[i for i,m in ids if i!='fSite' and m][0],str(model));s.wait_for_timeout(1500)
    site=save(s,lambda:s.click('#btnSave'),'site-set.html');h=site.read_text();ok('сайт сохраняется с движком текущей версии','OBJRT:START v'+VER in h)
    ok('нет ошибок JavaScript',not errors,errors[:5])
    b.close()
print(f'\nИтого: пройдено {ok_n}, ошибок {bad_n}')
